import type { SellerModel } from '@lembrai/core-domain';
import type { SellerDto, CreateSellerDto } from '@lembrai/core-domain/model/master/seller/dto';

export interface SellerExecutorInterface {
  runnerGet(
    model: SellerModel,
    input: { id?: string; slug?: string }
  ): Promise<SellerDto | null>;

  runnerCreate(
    model: SellerModel,
    input: { seller: CreateSellerDto }
  ): Promise<SellerDto>;

  runnerUpdate(
    model: SellerModel,
    input: { id: string; seller: Partial<SellerDto> }
  ): Promise<SellerDto | null>;

  runnerDelete(
    model: SellerModel,
    input: { id: string }
