// src/executors/seller/seller.ts
import { Request, Response } from 'express';
import { LembraiLogger } from '@lembrai/shared-utils';
import { getSellerModel } from '../../factoring-master';
import { handleExecutorError } from '../../error-utils';
import type { SellerExecutorInterface } from './seller-interface';

const logger = new LembraiLogger('SellerExecutor');

export class SellerExecutor implements SellerExecutorInterface {

  // Método estático para HTTP (usado por handlers)
  static async runnerGet(req: Request, res: Response): Promise<Response> {
    try {
      const id = req.query.id as string | undefined;
      const slug = req.query.slug as string | undefined;

      if (!id && !slug) {
        return res.status(400).json({ 
          error: 'id ou slug é obrigatório' 
        });
      }

      logger.info('Fetching seller', { id, slug });

      const model = await getSellerModel();
      const executor = new SellerExecutor();
      const seller = await executor.runnerGet(model, { id, slug });

      if (!seller) {
        return res.status(404).json({ error: 'Seller not found' });
      }

      return res.status(200).json(seller);

    } catch (error) {
      return handleExecutorError(logger, error, res, 'runnerGet');
    }
  }

  // Método de instância para business logic (testável)
  async runnerGet(
    model: SellerModel,
    input: { id?: string; slug?: string }
  ): Promise<SellerDto | null> {
    const { id, slug } = input;

    if (id) {
      return await model.findById(id);
    }

    if (slug) {
      return await model.findBySlug(slug);
    }

    return null;
  }

  // ... outros métodos
}

// ❌ RUIM - Sem interface, sem separação de concerns
export class SellerExecutor {
  static async get(req, res) {
    const seller = await db.query('SELECT * FROM sellers WHERE id = ?', [req.query.id]);
    res.json(seller);
  }
}
