### Models

```typescript
// ✅ BOM - Model com Drizzle ORM
// packages/core-domain/src/model/master/seller/seller-model.ts
import { LibSQLDatabase } from 'drizzle-orm/libsql';
import { eq, and, ilike, isNull } from 'drizzle-orm';
import { sellers } from '../../migration/master/schema';
import type { SellerDto, CreateSellerDto } from './dto';
import { LembraiLogger } from '@lembrai/shared-utils';

const logger = new LembraiLogger('SellerModel');

export class SellerModel {
  constructor(private readonly db: LibSQLDatabase) {}

  async findById(id: string): Promise<SellerDto | null> {
    logger.debug('Finding seller by ID', { id });

    const result = await this.db
      .select()
      .from(sellers)
      .where(and(
        eq(sellers.id, id),
        isNull(sellers.deleted_at)
      ))
      .limit(1);

    return result[0] ?? null;
  }

  async findBySlug(slug: string): Promise<SellerDto | null> {
    logger.debug('Finding seller by slug', { slug });

    const result = await this.db
      .select()
      .from(sellers)
      .where(and(
        eq(sellers.slug, slug),
        isNull(sellers.deleted_at)
      ))
      .limit(1);

    return result[0] ?? null;
  }

  async create(seller: CreateSellerDto): Promise<SellerDto> {
    logger.info('Creating seller', { slug: seller.slug });

    const result = await this.db
      .insert(sellers)
      .values({
        ...seller,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .returning();

    return result[0];
  }

  async update(id: string, seller: Partial<SellerDto>): Promise<SellerDto | null> {
    logger.info('Updating seller', { id });

    const result = await this.db
      .update(sellers)
      .set({
        ...seller,
        updated_at: new Date().toISOString(),
      })
      .where(eq(sellers.id, id))
      .returning();

    return result[0] ?? null;
  }

  async delete(id: string): Promise<void> {
    logger.info('Soft deleting seller', { id });

    await this.db
      .update(sellers)
      .set({
        deleted_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .where(eq(sellers.id, id));
  }
}

// ❌ RUIM - SQL raw, sem tipos, sem soft delete
export class SellerModel {
  async findById(id) {
    return await db.query('SELECT * FROM sellers WHERE id = ?', [id]);
  }

  async delete(id) {
    await db.query('DELETE FROM sellers WHERE id = ?', [id]);
  }
}
```

**Regras Models**:
- ✅ **SEMPRE** use classes
- ✅ Receba `LibSQLDatabase` no constructor
- ✅ Use Drizzle ORM (nunca SQL raw)
- ✅ Retorne DTOs tipados
- ✅ Use helpers Drizzle (`eq`, `and`, `or`, `ilike`)
- ✅ Limite resultados únicos com `.limit(1)`
- ✅ Soft delete (set `deleted_at`)
- ✅ Atualize `updated_at` em updates
- ✅ Logue operações importantes
- ❌ Nunca use SQL raw
- ❌ Nunca retorne objetos do Drizzle diretamente
- ❌ Nunca faça hard delete (use soft delete)

